// panel mark (dB, -12 ... +12) -> slide-pot position, linear between the 0.5 dB rows
inline double positionForMark (int band, double markDb)
{
    const double k = (std::min (12.0, std::max (-12.0, markDb)) + 12.0) * 2.0;
    const int i = std::min (kMarks - 2, (int) k);
    const double t = k - i;
    return kTaper[(size_t) band][(size_t) i] * (1 - t) + kTaper[(size_t) band][(size_t) (i + 1)] * t;
}
